import {chromium} from '@playwright/test';
import {readFileSync,writeFileSync,copyFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const dir='reference-captures/ordinary-original-run',id=process.env.UI_RUN_ID||'segment-1',duration=Number(process.env.UI_RUN_MS||180000);
const pixels='reference-captures/ordinary-native-run/pixels.py';
const sha=b=>createHash('sha256').update(b).digest('hex');
const log={started:new Date().toISOString(),scope:'Original Ruffle gameplay; public keyboard/mouse and screenshot pixels only. No AVM/game/storage/seed/clock access or edits. CV map-dot heuristic is provisional, no original health is inferred from it.',controllerSha256:sha(readFileSync(`${dir}/controller.mjs`)),pixelsSha256:sha(readFileSync(pixels)),steps:[],milestones:[],errors:[]};
const save=()=>writeFileSync(`${dir}/${id}.json`,JSON.stringify(log,null,2)+'\n');
let stopped=false;for(const s of ['SIGINT','SIGTERM'])process.once(s,()=>{stopped=true;log.interrupted=s;save()});
const browser=await chromium.connectOverCDP('http://127.0.0.1:9224');
const page=browser.contexts().flatMap(c=>c.pages()).find(p=>p.url()==='http://127.0.0.1:3104/');
if(!page)throw Error('Owned original page absent');
page.on('pageerror',e=>{log.errors.push(e.message);save()});
const stage=page.locator('ruffle-player');let held=new Set(),fire=false,overlay=false,lastReport=0,lastTarget=Date.now(),previous;
async function keys(next){for(const k of held)if(!next.includes(k))await page.keyboard.up(k);for(const k of next)if(!held.has(k))await page.keyboard.down(k);held=new Set(next)}
try{
 // Caller visually verifies a publicly paused game before each bounded segment.
 await page.keyboard.press('KeyP');await page.waitForTimeout(1000);
 const started=Date.now();
 while(Date.now()-started<duration&&!stopped){
  const path=`${dir}/${id}-current.png`;await stage.screenshot({path,scale:'css'});
  const cv=JSON.parse(execFileSync('python3',[pixels,path],{encoding:'utf8'}));
  const target=cv.targets[0],field=cv.field?.support>600&&cv.field?.meanResidual<1?cv.field:null;
  if(target)lastTarget=Date.now();
  let vx=0,vy=0,decision,aim=target??{x:500,y:225};
  if(target){const dx=target.x-275,dy=target.y-225,d=Math.max(1,Math.hypot(dx,dy)),toward=Math.max(-.8,Math.min(.85,(d-175)/110));vx=dx/d*toward-dy/d*.65;vy=dy/d*toward+dx/d*.65;decision='Aim/kite observed blue actor';
   if(previous?.target&&previous.field&&field){const dt=Math.max(.1,(Date.now()-previous.at)/1000),cx=field.x-previous.field.x,cy=field.y-previous.field.y;if(Math.hypot(target.x-previous.target.x-cx,target.y-previous.target.y-cy)<80)aim={x:target.x+Math.max(-50,Math.min(50,(target.x-previous.target.x-cx)/dt*d/500)),y:target.y+Math.max(-50,Math.min(50,(target.y-previous.target.y-cy)/dt*d/500))};}
  }else if(cv.pickups.length){const p=cv.pickups[0],d=Math.max(1,Math.hypot(p.x-275,p.y-225));vx=(p.x-275)/d;vy=(p.y-225)/d;decision='Collect observed green pickup';}
  else if(cv.mapDot.cleared||Date.now()-lastTarget>22000){vx=1;vy=field?Math.max(-.6,Math.min(.6,(field.y-225)/200)):0;decision='Explore east after clear-dot observation or extended empty view';}
  else if(field){const a=(Date.now()-started)/6500,dx=field.x+Math.cos(a)*300-275,dy=field.y+Math.sin(a)*300-225,d=Math.max(1,Math.hypot(dx,dy));vx=dx/d;vy=dy/d;decision='Search observed field';}
  else{vx=1;vy=0;decision='Search east until field/enemy visible';}
  const pickup=cv.pickups.find(p=>Math.hypot(p.x-275,p.y-225)<150);
  if(pickup){const dx=pickup.x-275,dy=pickup.y-225,d=Math.max(1,Math.hypot(dx,dy));vx=dx/d;vy=dy/d;decision+='; collect nearby pickup';}
  if(field&&target&&!cv.mapDot.cleared){const dx=field.x-275,dy=field.y-225,d=Math.max(1,Math.hypot(dx,dy));if(field.radius-d<100){vx=dx/d;vy=dy/d;decision+='; steer inward from observed wall';}}
  if(Date.now()-lastReport>15000){
   const text=execFileSync('tesseract',[path,'stdout','--psm','11'],{encoding:'utf8',stdio:['ignore','pipe','ignore']});
   const milestone=`${dir}/${id}-time-${Math.round((Date.now()-started)/1000)}.png`;copyFileSync(path,milestone);log.milestones.push({at:new Date().toISOString(),path:milestone,sha256:sha(readFileSync(milestone)),ocr:text});lastReport=Date.now();
   console.log(JSON.stringify({elapsed:Date.now()-started,targets:cv.targets.length,pickups:cv.pickups.length,decision,ocr:text.slice(0,600)}));
   if(/upgrade|congratulat|you win|paused/i.test(text)){overlay=true;log.overlay={at:new Date().toISOString(),text,path:milestone};save();break;}
  }
  const r=await stage.boundingBox();await page.mouse.move(r.x+Math.max(4,Math.min(546,aim.x))/550*r.width,r.y+Math.max(4,Math.min(446,aim.y))/450*r.height);
  if(!fire){await page.mouse.down();fire=true;}
  const next=[];if(vx>.22)next.push('KeyD');if(vx<-.22)next.push('KeyA');if(vy>.22)next.push('KeyS');if(vy<-.22)next.push('KeyW');await keys(next);
  log.steps.push({at:new Date().toISOString(),...cv,keys:next,aim,decision});save();previous={at:Date.now(),target,field};
  await page.waitForTimeout(250);await keys([]);
 }
}catch(e){log.failure=String(e);console.error(e);}
finally{
 await keys([]);if(fire)await page.mouse.up();
 if(!overlay)await page.keyboard.press('KeyP');await page.waitForTimeout(600);
 const path=`${dir}/${id}-end.png`;await stage.screenshot({path,scale:'css'});
 log.ended=new Date().toISOString();log.endScreenshot={path,sha256:sha(readFileSync(path))};log.pauseRequested=!overlay;save();
 console.log(JSON.stringify({steps:log.steps.length,overlay:log.overlay??null,failure:log.failure,ended:log.ended}));await browser.close();
}
